-- Additive standalone backup metadata. No capture starts on installation.
CREATE TABLE IF NOT EXISTS venue_business_backup_runs (
 venue_id INTEGER PRIMARY KEY REFERENCES venues(id), account_id INTEGER NOT NULL UNIQUE REFERENCES accounts(id),
 run_id TEXT NOT NULL UNIQUE, actor_id INTEGER NOT NULL REFERENCES accounts(id),
 phase TEXT NOT NULL CHECK(phase IN ('CAPTURE','COMPLETE','ABORTED')), paused INTEGER NOT NULL CHECK(paused IN (0,1)),
 backup_key TEXT,backup_hash TEXT,receipt_hash TEXT,progress_json TEXT,
 revision INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,expires_at TEXT
);
CREATE TRIGGER IF NOT EXISTS business_backup_pause_domain_data_insert BEFORE INSERT ON domain_data WHEN EXISTS(SELECT 1 FROM venue_business_backup_runs p WHERE p.paused=1 AND p.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ((NEW.account_id=p.account_id))) BEGIN SELECT RAISE(ABORT,'BUSINESS_BACKUP_PAUSED'); END;
CREATE TRIGGER IF NOT EXISTS business_backup_pause_domain_data_update BEFORE UPDATE ON domain_data WHEN EXISTS(SELECT 1 FROM venue_business_backup_runs p WHERE p.paused=1 AND p.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ((OLD.account_id=p.account_id) OR (NEW.account_id=p.account_id))) BEGIN SELECT RAISE(ABORT,'BUSINESS_BACKUP_PAUSED'); END;
CREATE TRIGGER IF NOT EXISTS business_backup_pause_domain_data_delete BEFORE DELETE ON domain_data WHEN EXISTS(SELECT 1 FROM venue_business_backup_runs p WHERE p.paused=1 AND p.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ((OLD.account_id=p.account_id))) BEGIN SELECT RAISE(ABORT,'BUSINESS_BACKUP_PAUSED'); END;
